import React, { useEffect, useRef, useState } from './vendor/react.mjs';
import { createRoot } from './vendor/react-dom.mjs';
import htm from './vendor/htm.mjs';
const html = htm.bind(React.createElement);
const fmt = (n, digits=4) => Number(n).toLocaleString('id-ID', { minimumFractionDigits: digits, maximumFractionDigits: digits });
const number = n => Number(n).toLocaleString('id-ID');
const paths = {
  search: 'm21 21-4.4-4.4M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
  arrow: 'M5 12h14m-6-6 6 6-6 6',
  flow: 'M6 3v12a3 3 0 0 0 3 3h9M3 3h6v6H3zM15 15h6v6h-6zM15 3h6v6h-6zM9 6h6',
  chart: 'M4 3v17h17M8 15v-4m5 4V7m5 8V4',
  book: 'M12 6c-3-3-7-3-10-2v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 2zm0 0v15',
  check: 'm5 12 4 4L19 6',
  chevron: 'm9 5 7 7-7 7',
  download: 'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
  close: 'm6 6 12 12M6 18 18 6',
  info: 'M12 11v6m0-10v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  layers: 'm12 3 10 5-10 5L2 8 12 3zm-10 9 10 5 10-5M2 16l10 5 10-5',
  cpu: 'M7 7h10v10H7zM9 1v6m6-6v6M9 17v6m6-6v6M1 9h6m-6 6h6m10-6h6m-6 6h6',
  spark: 'm12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3',
};
function Icon({name, size=18, className=''}) {
  return html`<svg width=${size} height=${size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className=${className}><path d=${paths[name] || paths.info}/></svg>`;
}
function SectionTitle({number: index, title, subtitle, children}) {
  return html`<section className="card p-5 md:p-6"><div className="mb-4 flex gap-3"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-mint text-xs font-semibold text-forest">${index}</span><div><h3 className="text-sm font-semibold">${title}</h3><p className="mt-1 text-xs leading-relaxed text-muted">${subtitle}</p></div></div>${children}</section>`;
}
function Vector({values}) {
  return html`<div className="vector-grid" role="img" aria-label="Peta 384 nilai embedding query; hijau positif dan jingga negatif">${values.map((v,i) => html`<span key=${i} title=${`Dimensi ${i+1}: ${v.toFixed(6)}`} style=${{backgroundColor:v>=0?`rgba(32,119,83,${Math.min(.95,.13+Math.abs(v)*7)})`:`rgba(196,125,75,${Math.min(.95,.13+Math.abs(v)*7)})`}}/>`)}</div>`;
}
function Histogram({data}) {
  const max = Math.max(...data.counts,1);
  return html`<div><svg viewBox="0 0 600 100" className="h-24 w-full" role="img" aria-label="Distribusi jumlah dokumen berdasarkan skor cosine">${data.counts.map((count,i) => html`<rect key=${i} x=${i*25+1} y=${95-count/max*85} width="20" height=${count/max*85} rx="3" fill=${i>19?'#276b53':'#b8d0c1'}><title>${count} dokumen</title></rect>`)}</svg><div className="flex justify-between text-[10px] text-muted"><span>Skor terendah ${fmt(data.minimum)}</span><span>Skor tertinggi ${fmt(data.maximum)}</span></div></div>`;
}
function Trace({data, onDetail}) {
  if (!data) return html`<div className="card p-10 text-center"><div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-mint text-forest"><${Icon} name="flow" size=${24}/></div><h3 className="font-semibold">Ikuti perjalanan sebuah query</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-muted">Jalankan pencarian terlebih dahulu. Setiap tahap akan menampilkan output nyata dari query yang kamu masukkan.</p></div>`;
  return html`<div className="space-y-4">
    <${SectionTitle} number="01" title="Teks dirapikan" subtitle="Hanya whitespace yang dirapikan. Makna, negasi, angka, dan tanda baca dipertahankan.">
      <div className="grid gap-3 md:grid-cols-2"><div className="trace-output"><p className="eyebrow mb-2">Input asli</p><p className="whitespace-pre-wrap break-words">${data.original}</p></div><div className="trace-output"><p className="eyebrow mb-2">Setelah normalisasi</p><p className="break-words">${data.normalized}</p></div></div>
    </${SectionTitle}>
    <${SectionTitle} number="02" title="Teks dipecah menjadi token" subtitle="Tokenizer bawaan MiniLM mengubah potongan teks menjadi ID. Satu token belum tentu satu kata.">
      <div className="mb-3 flex flex-wrap gap-2"><span className="pill">${data.tokenCount} token input</span><span className="pill">${data.usedTokens} token dipakai</span><span className="pill">Batas 256 token</span></div>
      ${data.truncated && html`<p className="mb-3 rounded-lg bg-amber-50 p-3 text-xs text-amber-800">Input terlalu panjang. Hanya 256 token pertama yang digunakan, termasuk token khusus model.</p>`}
      <div className="flex max-h-48 flex-wrap gap-1.5 overflow-auto rounded-xl bg-paper p-3">${data.tokens.map((t,i) => html`<span key=${i} className="rounded-md border border-line bg-white px-2 py-1 text-xs"><span className="font-mono text-forest">${t.text || '∅'}</span><span className="ml-1.5 text-[9px] text-muted">${t.id}</span></span>`)}</div>
    </${SectionTitle}>
    <${SectionTitle} number="03" title="Query menjadi vektor 384 dimensi" subtitle=${`Model ${data.modelLabel} menghasilkan vektor setiap token. Mean pooling menggabungkannya, lalu normalisasi L2 membuat panjang vektor menjadi 1.`}>
      <${Vector} values=${data.vector}/><div className="mt-3 flex flex-wrap justify-between gap-2 text-[10px] text-muted"><span>Hijau: nilai positif · jingga: nilai negatif</span><span>Norma L2: ${fmt(data.normAfter,6)} · ${fmt(data.encodingMs,0)} ms</span></div>
      <details className="mt-4"><summary className="cursor-pointer text-xs font-medium text-forest">Lihat 12 nilai pertama</summary><div className="mt-2 grid grid-cols-3 gap-2 md:grid-cols-6">${data.vector.slice(0,12).map((v,i) => html`<div key=${i} className="rounded-lg bg-paper p-2 text-center"><p className="text-[9px] text-muted">Dimensi ${i+1}</p><p className="mt-1 font-mono text-[10px]">${v.toFixed(5)}</p></div>`)}</div></details>
      <p className="mt-3 text-xs leading-5 text-muted">Dimensi embedding adalah fitur numerik yang dipelajari. Satu dimensi tidak dapat langsung diartikan sebagai satu kata atau topik tertentu.</p>
    </${SectionTitle}>
    <${SectionTitle} number="04" title="Dibandingkan dengan seluruh corpus" subtitle="Embedding dokumen sudah disiapkan dengan model yang sama. Dot product vektor yang ternormalisasi sama dengan cosine similarity.">
      <div className="trace-output mb-4 text-center font-mono text-sm">cos(q, d) = Σ qᵢ × dᵢ <span className="text-muted">(384 dimensi)</span></div><${Histogram} data=${data.histogram}/>
      <div className="mt-4 grid grid-cols-3 gap-3 text-center"><div><p className="text-lg font-semibold">${number(data.documents)}</p><p className="text-[10px] text-muted">dokumen dibandingkan</p></div><div><p className="text-lg font-semibold">${fmt(data.histogram.mean)}</p><p className="text-[10px] text-muted">rata-rata cosine</p></div><div><p className="text-lg font-semibold">${fmt(data.rankingMs,0)} ms</p><p className="text-[10px] text-muted">perhitungan & ranking</p></div></div>
    </${SectionTitle}>
    <${SectionTitle} number="05" title="Diurutkan, lalu metadata diambil" subtitle="Seluruh skor diurutkan dari tertinggi. ID hasil digunakan untuk mengambil judul dan abstrak asli, tanpa membuat ringkasan baru.">
      <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Rank</th><th>Dokumen sumber</th><th>Cosine</th></tr></thead><tbody>${data.results.map(r => html`<tr key=${r.id}><td>${r.rank}</td><td><button onClick=${() => onDetail(r)} className="text-left font-medium hover:underline">${r.title}</button><p className="mt-1 text-[10px] text-muted">ID ${r.id}</p></td><td className="font-mono">${fmt(r.score)}</td></tr>`)}</tbody></table></div>
    </${SectionTitle}>
  </div>`;
}

function DetailModal({result, breakdown, onClose, query}) {
  const modal = useRef(null); const [tab,setTab] = useState('abstract');
  useEffect(() => {
    const previous = document.activeElement;
    modal.current?.focus();
    const handler = event => {
      if (event.key === 'Escape') onClose();
      if (event.key === 'Tab') {
        const items = [...modal.current.querySelectorAll('button, a, summary, [tabindex="0"]')];
        if (!items.length) return;
        const first=items[0],last=items[items.length-1];
        if (event.shiftKey && (document.activeElement===first || document.activeElement===modal.current)) {event.preventDefault();last.focus();}
        else if (!event.shiftKey && document.activeElement===last) {event.preventDefault();first.focus();}
      }
    };
    document.addEventListener('keydown',handler); document.body.style.overflow='hidden';
    return () => {document.removeEventListener('keydown',handler);document.body.style.overflow='';previous?.focus();};
  },[]);
  return html`<div className="modal-backdrop fixed inset-0 z-50 flex items-center justify-center p-3 md:p-8" onClick=${event=>{if(event.target===event.currentTarget)onClose();}}><div ref=${modal} tabIndex="-1" role="dialog" aria-modal="true" aria-labelledby="article-title" className="max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white p-6 shadow-xl md:p-8">
    <div className="flex items-center justify-between"><span className="eyebrow">Dokumen ${result.id} · peringkat ${result.rank}</span><button onClick=${onClose} className="rounded-lg p-2 hover:bg-paper" aria-label="Tutup rincian artikel"><${Icon} name="close"/></button></div>
    <h2 id="article-title" className="mt-3 text-xl font-semibold leading-snug">${result.title}</h2>
    <div className="mt-4 flex flex-wrap items-center gap-2"><span className="pill bg-mint text-forest">Cosine ${fmt(result.score)}</span><span className="pill">Corpus BEIR–SciFact</span>${result.relevant!==null && html`<span className="pill">${result.relevant?'Positive menurut qrels':'Tidak berlabel positive'}</span>`}</div>
    <div className="mb-5 mt-6 flex gap-6 border-b border-line"><button className=${`tab ${tab==='abstract'?'active':''}`} onClick=${()=>setTab('abstract')}>Abstrak lengkap</button><button className=${`tab ${tab==='score'?'active':''}`} onClick=${()=>setTab('score')}>Dari mana skor ini?</button></div>
    ${tab==='abstract' ? html`<p className="whitespace-pre-line text-sm leading-7 text-slate-600">${result.abstract}</p><div className="mt-6 rounded-xl bg-paper p-4 text-xs leading-5 text-muted">Judul dan abstrak diambil langsung dari corpus. Encoder memproses gabungan judul–abstrak hingga 256 token; tampilan ini tetap memuat abstrak lengkap.</div>` : html`<div><p className="text-sm leading-6 text-muted">Skor berasal dari penjumlahan hasil kali embedding query dan dokumen. Berikut delapan dimensi dengan kontribusi absolut terbesar. Seluruh 384 dimensi tetap digunakan.</p>
      ${!breakdown ? html`<p className="mt-4 text-sm">Menghitung rincian…</p>` : html`<div className="mt-4 overflow-x-auto"><table className="data-table"><thead><tr><th>Dimensi</th><th>Query qᵢ</th><th>Dokumen dᵢ</th><th>qᵢ × dᵢ</th></tr></thead><tbody>${breakdown.largest.map(row=>html`<tr key=${row.dim}><td>${row.dim+1}</td><td className="font-mono">${row.query.toFixed(6)}</td><td className="font-mono">${row.document.toFixed(6)}</td><td className=${`font-mono ${row.product<0?'text-amber-700':'text-emerald-700'}`}>${row.product.toFixed(6)}</td></tr>`)}<tr><td colSpan="3">Jumlah kontribusi 376 dimensi lainnya</td><td className="font-mono">${breakdown.rest.toFixed(6)}</td></tr><tr><td colSpan="3" className="font-semibold">Total cosine similarity</td><td className="font-mono font-semibold">${breakdown.score.toFixed(6)}</td></tr></tbody></table><p className="mt-3 text-xs text-muted">Norma embedding dokumen: ${fmt(breakdown.documentNorm,6)}</p></div>`}
      <div className="mt-5 rounded-xl bg-mint p-4 text-xs leading-6 text-forest">Nilai positif menambah skor, nilai negatif menguranginya. Ini menjelaskan asal perhitungan, bukan alasan ilmiah artikel mendukung query. Dimensi bukan kata, dan cosine bukan probabilitas relevansi.</div>
    </div>`}
    <div className="mt-6 border-t border-line pt-4 text-xs leading-5 text-muted">Query: “${query}” · Hasil retrieval perlu diperiksa melalui isi artikel.</div>
  </div></div>`;
}

function Metrics({manifest}) {
  if (!manifest) return html`<p className="p-6 text-sm text-muted">Memuat hasil eksperimen…</p>`;
  return html`<div className="space-y-5"><div className="card p-6"><p className="eyebrow">Eksperimen notebook laptop</p><h2 className="mt-3 text-2xl font-semibold">Apa yang berubah setelah training?</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-muted">Evaluasi pada 300 query test dan corpus yang sama. Angka ini berasal dari eksperimen tersimpan, bukan penilaian otomatis untuk query bebas yang kamu ketik.</p><div className="mt-8 grid gap-7 md:grid-cols-3">${Object.keys(manifest.metrics.pretrained).map(metric=>html`<div key=${metric}><h3 className="text-sm font-semibold">${metric}</h3>${[['pretrained','Model awal','#8ca99b'],['finetuned','Setelah fine-tuning','#206b50']].map(([key,label,color])=>html`<div key=${key} className="mt-4"><div className="mb-2 flex justify-between text-xs"><span className="text-muted">${label}</span><span className="font-mono">${fmt(manifest.metrics[key][metric])}</span></div><div className="h-2 overflow-hidden rounded-full bg-paper"><div style=${{width:`${manifest.metrics[key][metric]*100}%`,backgroundColor:color}} className="h-full rounded-full"/></div></div>`)}<p className="mt-4 text-xs font-medium text-emerald-700">+${fmt(manifest.metrics.finetuned[metric]-manifest.metrics.pretrained[metric])} perubahan absolut</p></div>`)}</div></div>
    <div className="grid gap-4 md:grid-cols-3">${[['63','query membaik','pada nDCG@10'],['23','query mulai berhasil','menemukan positive di Top-10'],['29','query menurun','pada nDCG@10']].map(([v,t,desc])=>html`<div key=${t} className="card p-6"><p className="font-display text-4xl">${v}</p><p className="mt-3 text-sm font-medium">${t}</p><p className="mt-1 text-xs text-muted">${desc}</p></div>`)}</div>
    <div className="card p-6"><p className="eyebrow">Tahap offline ? sebelum pencarian</p><h2 className="mt-3 text-lg font-semibold">Bagaimana model ini disiapkan?</h2><div className="mt-5 grid gap-3 md:grid-cols-4">${[['809 query train','Dipisahkan dari test'],['919 pasangan positif','Query dan judul?abstrak'],['3 epoch MNRL','Bobot model diperbarui'],['5.183 embedding','Corpus memakai model yang sama']].map(([title,description])=>html`<div key=${title} className="rounded-xl bg-paper p-4"><p className="text-xs font-semibold">${title}</p><p className="mt-2 text-[10px] leading-5 text-muted">${description}</p></div>`)}</div><div className="mt-6 grid items-center gap-5 md:grid-cols-2"><img src="./data/training_loss.png" alt="Loss training MNRL asli dari notebook: berfluktuasi tetapi cenderung lebih rendah pada bagian akhir" className="w-full rounded-xl border border-line"/><div><h3 className="text-sm font-semibold">Loss training fine-tuned</h3><p className="mt-3 text-xs leading-6 text-muted">Loss pertama tercatat 0,0606; terakhir tercatat 0,0118. Training selesai pada step 342 selama sekitar 22 menit 32 detik. Catatan loss terakhir berada di step 340.</p><p className="mt-3 text-xs leading-6 text-muted">Kurva ini hanya milik training SciFact. Riwayat training asli pretrained tidak tersedia. Loss yang lebih rendah bukan jaminan ranking setiap query membaik.</p><p className="mt-3 text-xs leading-6 text-muted">71,02% dokumen melewati batas 256 token. Abstrak lengkap tetap disimpan untuk ditampilkan, tetapi encoder hanya melihat bagian yang masuk batas input.</p></div></div></div>
    <div className="rounded-xl border border-line bg-mint p-5 text-sm leading-6 text-forest">Model akhir tiga epoch lebih baik secara rata-rata daripada pretrained pada run ini. Belum ada validation untuk memilih checkpoint terbaik. Loss yang turun dan skor cosine tinggi tidak menggantikan evaluasi retrieval.</div>
  </div>`;
}

function Comparison({comparison,onSelect,onDetail}) {
  const overlap=comparison.pretrained.results.filter(r=>comparison.finetuned.results.some(d=>d.id===r.id)).length;
  const union=[...new Map([...comparison.finetuned.results,...comparison.pretrained.results].map(r=>[r.id,r])).values()];
  return html`<section className="card mb-5 p-5 md:p-6"><div className="flex flex-wrap justify-between gap-3"><div><p className="eyebrow">Query sama · dua encoder</p><h2 className="mt-2 font-semibold">Sebelum dan setelah fine-tuning</h2></div><span className="pill">${overlap} dokumen sama di kedua Top-${comparison.finetuned.topK}</span></div>
    <p className="mt-3 text-xs leading-6 text-muted">Setiap model memakai embedding corpus pasangannya sendiri. Bandingkan artikel dan posisinya; skor cosine antar-model tidak otomatis berarti peningkatan relevansi.</p>
    ${comparison.finetuned.queryMetrics&&html`<div className="mt-4 overflow-x-auto"><table className="data-table"><thead><tr><th>Metrik query benchmark ini</th><th>Pretrained</th><th>Fine-tuned</th></tr></thead><tbody>${Object.keys(comparison.finetuned.queryMetrics).map(m=>html`<tr key=${m}><td>${m}</td><td>${fmt(comparison.pretrained.queryMetrics[m])}</td><td className="font-semibold text-forest">${fmt(comparison.finetuned.queryMetrics[m])}</td></tr>`)}</tbody></table></div>`}
    <div className="mt-5 grid gap-4 md:grid-cols-2">${['pretrained','finetuned'].map(model=>html`<div key=${model} className="min-w-0 rounded-xl border border-line p-4"><div className="mb-3 flex items-center justify-between gap-2"><h3 className="text-xs font-semibold">${comparison[model].modelLabel}</h3><button className="text-[10px] font-medium text-forest underline" onClick=${()=>onSelect(comparison[model])}>Lihat alur model ini</button></div><div className="space-y-3">${comparison[model].results.map(r=>html`<button key=${r.id} onClick=${()=>onDetail(r)} className="block w-full border-t border-line pt-3 text-left"><div className="flex items-center justify-between gap-3 text-[10px] text-muted"><span>#${r.rank} · ${r.id}</span><span className="font-mono text-forest">${fmt(r.score)}</span></div><p className="mt-1 line-clamp-2 text-xs font-medium leading-5">${r.title}</p>${r.relevant!==null&&html`<p className=${`mt-1 text-[9px] ${r.relevant?'text-emerald-700':'text-muted'}`}>${r.relevant?'✓ Positive qrels':'Tidak berlabel positive'}</p>`}</button>`)}</div></div>`)}</div>
    <details className="mt-5"><summary className="cursor-pointer text-xs font-medium text-forest">Perubahan posisi dokumen</summary><div className="mt-2 overflow-x-auto"><table className="data-table"><thead><tr><th>Document ID</th><th>Pretrained</th><th>Fine-tuned</th></tr></thead><tbody>${union.map(r=>html`<tr key=${r.id}><td>${r.id}<p className="mt-1 max-w-xs text-[10px] text-muted">${r.title}</p></td><td>${comparison.pretrained.allRanking.find(d=>d.id===r.id)?.rank??'>100'}</td><td>${comparison.finetuned.allRanking.find(d=>d.id===r.id)?.rank??'>100'}</td></tr>`)}</tbody></table></div></details>
  </section>`;
}

function App() {
  const [view,setView]=useState('search'),[query,setQuery]=useState(''),[topK,setTopK]=useState(5);
  const [manifest,setManifest]=useState(null),[status,setStatus]=useState('idle'),[progress,setProgress]=useState(0),[message,setMessage]=useState('');
  const [data,setData]=useState(null),[tab,setTab]=useState('results'),[error,setError]=useState(''),[selected,setSelected]=useState(null),[breakdown,setBreakdown]=useState(null),[verification,setVerification]=useState(null);
  const [modelMode,setModelMode]=useState('finetuned'),[comparison,setComparison]=useState(null);
  const worker=useRef(null),textarea=useRef(null),searching=useRef(false),detailIndex=useRef(null);
  useEffect(()=>{
    fetch('./data/manifest.json').then(r=>{if(!r.ok)throw new Error('Data aplikasi belum tersedia. Jalankan persiapan aset.');return r.json();}).then(setManifest).catch(e=>setError(e.message));
    const w=new Worker(new URL('./search-engine.js',import.meta.url),{type:'module'});worker.current=w;
    w.onmessage=({data:event})=>{
      if(event.type==='loading'){setStatus('loading');setMessage(event.message);setProgress(event.progress);}
      if(event.type==='ready'){setManifest(event.manifest);setProgress(100);setStatus(current=>current==='verifying'?'verifying':searching.current?'searching':'ready');}
      if(event.type==='stage'){setStatus('searching');setMessage(event.message);}
      if(event.type==='result'){setData(event.data);setComparison(null);setStatus('ready');searching.current=false;}
      if(event.type==='comparison'){setComparison({pretrained:event.pretrained,finetuned:event.finetuned});setData(event.finetuned);setStatus('ready');searching.current=false;}
      if(event.type==='detail' && event.index===detailIndex.current?.index && event.variant===detailIndex.current?.variant)setBreakdown(event.breakdown);
      if(event.type==='verified'){setVerification(event.results);setStatus('ready');}
      if(event.type==='error'){setError(event.message);setStatus('error');searching.current=false;}
    };
    w.onerror=()=>{setError('Runtime browser gagal dimuat. Pastikan aplikasi dibuka melalui HTTP/HTTPS dan seluruh folder vendor serta model ikut diunggah.');setStatus('error');searching.current=false;};
    return()=>w.terminate();
  },[]);
  const busy=['loading','searching','verifying'].includes(status);
  const openDetail=result=>{if(busy)return;setSelected(result);setBreakdown(null);detailIndex.current={index:result.index,variant:result.variant};worker.current.postMessage({type:'detail',index:result.index,variant:result.variant});};
  const search=event=>{
    event?.preventDefault();if(busy)return;
    if(!query.trim()){setError('Tulis kalimat pencarian terlebih dahulu.');textarea.current?.focus();return;}
    setError('');setSelected(null);setStatus('searching');setMessage('Menyiapkan pencarian…');searching.current=true;
    worker.current.postMessage({type:'search',query,topK,variant:modelMode});
  };
  const exportResults=()=>{
    const blob=new Blob([JSON.stringify(comparison||data,null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='scifind-hasil-pencarian.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  };
  const nav=[['search','search','Pencarian'],['pipeline','flow','Alur perhitungan'],['metrics','chart','Hasil eksperimen'],['about','book','Tentang penelitian']];
  const changeView=id=>{setView(id);if(id==='search')setTab('results');};
  return html`<div className="min-h-screen">
    <aside className="fixed inset-y-0 left-0 z-20 hidden w-[236px] flex-col border-r border-line bg-white px-5 py-8 xl:flex">
      <a href="#" onClick=${e=>{e.preventDefault();changeView('search');}} className="mb-12 flex items-center gap-3 px-2"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-forest font-display text-2xl text-[#d2e8cc]">S.</span><span className="text-xl font-semibold tracking-tight">SciFind<span className="text-emerald-700">.</span></span></a>
      <p className="eyebrow mb-3 px-3">Ruang eksplorasi</p><nav className="space-y-1" aria-label="Navigasi utama">${nav.map(([id,icon,label])=>html`<button key=${id} onClick=${()=>changeView(id)} className=${`nav-item w-full ${view===id?'active':''}`} aria-current=${view===id?'page':undefined}><${Icon} name=${icon}/>${label}</button>`)}</nav>
      <div className="mt-auto"><div className="dot-grid rounded-2xl border border-line p-4"><span className="mb-3 inline-flex rounded-lg bg-white p-2 text-forest"><${Icon} name="cpu"/></span><p className="text-xs font-semibold">Penelitian dalam browser</p><p className="mt-2 text-[11px] leading-5 text-muted">Query diproses di perangkatmu. Model final, tanpa training ulang.</p></div><p className="mt-5 px-2 text-[10px] text-muted">TKI · Kelompok 06<br/>BEIR–SciFact Research Project</p></div>
    </aside>
    <div className="xl:ml-[236px]">
      <header className="border-b border-line bg-white/80"><div className="mx-auto flex h-[76px] max-w-[1450px] items-center justify-between gap-3 px-5 md:px-10"><div className="flex items-center gap-3"><span className="font-display text-xl text-forest xl:hidden">SciFind.</span><span className="hidden text-[10px] font-medium uppercase tracking-[.15em] text-muted md:inline">Research workspace</span><span className="hidden text-line md:inline">/</span><span className="hidden text-xs text-ink md:inline">Semantic search</span></div><span className="pill"><span className=${`h-1.5 w-1.5 rounded-full ${status==='ready'?'bg-emerald-600':busy?'bg-amber-500 pulse-dot':'bg-slate-400'}`}/>${status==='ready'?'Model siap':busy?'Sedang memproses':'Model lokal · FP32'}</span></div>
        <nav className="flex gap-1 overflow-x-auto px-4 pb-3 xl:hidden" aria-label="Navigasi mobile">${nav.map(([id,icon,label])=>html`<button key=${id} onClick=${()=>changeView(id)} className=${`nav-item shrink-0 !py-2 !text-xs ${view===id?'active':''}`}>${label}</button>`)}</nav>
      </header>
      <main className="mx-auto max-w-[1450px] px-5 py-8 md:px-10 md:py-10">
        ${view==='search'||view==='pipeline'?html`<section className="mb-8 flex items-end justify-between gap-5"><div><div className="mb-3 flex items-center gap-2"><span className="h-1 w-5 bg-emerald-700"/><p className="eyebrow">Scientific discovery, made clearer</p></div><h1 className="font-display text-[38px] leading-[1.13] tracking-tight md:text-[46px]">Temukan makna.<br/><span className="text-[#6c8276]">Bukan sekadar kata.</span></h1><p className="mt-4 max-w-xl text-sm leading-6 text-muted">Jelajahi abstrak ilmiah dengan pencarian semantik.<br className="hidden md:block"/>Lihat setiap langkah yang membawa query menjadi hasil.</p></div><div className="hidden pb-2 text-right lg:block"><p className="font-display text-3xl">${manifest?number(manifest.documents):'5.183'}</p><p className="mt-1 text-[10px] uppercase tracking-widest text-muted">Abstrak ilmiah · SciFact</p></div></section>
        <div className="grid items-start gap-6 2xl:grid-cols-[minmax(0,1fr)_270px]"><div className="min-w-0">
          <form onSubmit=${search} className="card mb-6 p-5 shadow-soft md:p-6"><label htmlFor="query" className="mb-3 flex items-center gap-2 text-xs font-semibold"><${Icon} name="search" size=${16}/>Apa yang ingin kamu telusuri?</label><div className="mb-3 flex flex-wrap items-center gap-2"><span className="mr-2 text-[10px] text-muted">Model pencarian</span>${[['pretrained','Pretrained'],['finetuned','Fine-tuned'],['compare','Bandingkan keduanya']].map(([id,label])=>html`<button key=${id} type="button" disabled=${busy} aria-pressed=${modelMode===id} onClick=${()=>setModelMode(id)} className=${`rounded-lg border px-3 py-2 text-[11px] transition ${modelMode===id?'border-forest bg-forest text-white':'border-line bg-white text-muted hover:bg-mint'}`}>${label}</button>`)}</div><textarea ref=${textarea} id="query" value=${query} onChange=${e=>setQuery(e.target.value)} maxLength="12000" rows="2" placeholder="Does vitamin D improve bone density?" className="w-full resize-y rounded-xl border border-line bg-paper px-4 py-3 text-sm leading-6 placeholder:text-[#a3ada6] focus:border-emerald-600" onKeyDown=${e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey))search(e);}}/><div className="mt-3 flex flex-wrap items-center justify-between gap-3"><p className="text-[10px] text-muted">Gunakan bahasa Inggris · ${query.length}/12.000 karakter</p><div className="flex items-center gap-3"><label className="flex items-center gap-2 text-xs text-muted">Hasil<select aria-label="Jumlah hasil pencarian" value=${topK} onChange=${e=>setTopK(Number(e.target.value))} className="rounded-lg border border-line bg-white px-2 py-2 text-ink">${[5,10,20].map(n=>html`<option key=${n} value=${n}>Top-${n}</option>`)}</select></label><button disabled=${busy} className="btn" type="submit">${busy?html`<span className="spinner"/>`:html`<${Icon} name="search" size=${16}/>`}${busy?'Memproses…':'Telusuri artikel'}${!busy&&html`<${Icon} name="arrow" size=${15}/>`}</button></div></div><div className="mt-5 flex flex-wrap items-center gap-2 border-t border-line pt-4"><span className="mr-1 text-[10px] text-muted">Coba query</span>${[['Vitamin D & tulang','Does vitamin D improve bone density?'],['MDA5 & imunitas','The PPR MDA5 has two N-terminal CARD domains.'],['Biomaterial','0-dimensional biomaterials show inductive properties.']].map(([label,text])=>html`<button key=${label} type="button" disabled=${busy} onClick=${()=>{setQuery(text);textarea.current?.focus();}} className="rounded-full border border-line px-3 py-1.5 text-[10px] text-muted transition hover:border-emerald-700 hover:text-forest">${label}<span className="ml-2">↗</span></button>`)}</div></form>
          ${busy&&html`<div className="card mb-5 p-4" role="status" aria-live="polite"><div className="flex items-center gap-3 text-xs text-forest"><span className="spinner"/><span>${message || 'Menyiapkan model…'}</span></div>${status==='loading'&&html`<div className="mt-3 h-1.5 rounded-full bg-mint"><div className="h-full rounded-full bg-emerald-700 transition-all" style=${{width:`${progress}%`}}/></div><p className="mt-2 text-[10px] leading-5 text-muted">Pemuatan pertama mencakup model ±91 MB dan runtime. Pencarian berikutnya memakai model di memori.</p>`}</div>`}
          ${error&&html`<div role="alert" className="mb-5 rounded-xl border border-red-200 bg-red-50 p-4 text-xs leading-6 text-red-800">${error}</div>`}
          ${data&&html`<div className="mb-4 flex flex-wrap items-end justify-between gap-3"><div><p className="eyebrow mb-1">Hasil pencarian terakhir</p><p className="max-w-lg break-words text-sm font-medium">“${data.normalized}”</p></div><button onClick=${exportResults} className="btn-secondary"><${Icon} name="download" size=${14}/>Ekspor hasil</button></div>`}
          ${comparison&&html`<${Comparison} comparison=${comparison} onSelect=${result=>{setData(result);setTab('trace');}} onDetail=${openDetail}/>`}
          ${data&&html`<p className="mb-3 text-[11px] font-semibold text-forest">Hasil dan alur aktif: ${data.modelLabel}</p>`}
          <div className="mb-5 flex gap-7 border-b border-line"><button onClick=${()=>{setTab('results');setView('search');}} className=${`tab ${view==='search'&&tab==='results'?'active':''}`}>Hasil pencarian ${data?`(${data.results.length})`:''}</button><button onClick=${()=>setTab('trace')} className=${`tab ${view==='pipeline'||tab==='trace'?'active':''}`}><span className="inline-flex items-center gap-2"><${Icon} name="flow" size=${15}/>Alur perhitungan</span></button></div>
          ${view==='pipeline'||tab==='trace'?html`<${Trace} data=${data} onDetail=${openDetail}/>`:data?html`<div><div className="mb-4 flex flex-wrap items-center justify-between gap-2 text-[11px] text-muted"><span>${data.results.length} dari ${number(data.documents)} dokumen · ${fmt(data.totalMs,0)} ms setelah model siap</span><span>Urutan: cosine tertinggi</span></div>${data.truncated&&html`<p className="mb-4 rounded-lg bg-amber-50 p-3 text-xs text-amber-800">Query melebihi 256 token. Sebagian teks dipotong. Lihat token pada Alur perhitungan.</p>`}${data.benchmark&&html`<div className="mb-4 rounded-xl bg-mint px-4 py-3 text-xs leading-5 text-forest">Query benchmark #${data.benchmark.id} · ${data.benchmark.relevantFound} dari ${data.benchmark.relevantCount} positive qrels ditemukan pada Top-${data.topK}. Label hanya tersedia untuk query benchmark yang cocok persis.</div>`}<div className="space-y-4">${data.results.map((r,i)=>html`<article key=${r.id} className="result-card card p-5 transition md:p-6" style=${{animationDelay:`${i*35}ms`}}><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2.5"><span className="flex h-6 w-6 items-center justify-center rounded-md bg-paper text-[10px] font-semibold text-muted">${String(r.rank).padStart(2,'0')}</span><span className="text-[10px] text-muted">SCIFACT · ${r.id}</span></div><span className="rounded-full bg-mint px-3 py-1 text-xs font-semibold tabular-nums text-forest">${fmt(r.score)}<span className="ml-1 text-[9px] font-normal">cosine</span></span></div><button onClick=${()=>openDetail(r)} className="mt-4 text-left text-base font-semibold leading-6 transition hover:text-emerald-700">${r.title}</button><p className="mt-3 line-clamp-3 text-xs leading-6 text-muted">${r.abstract}</p><div className="mt-5 flex items-center justify-between border-t border-line pt-3"><span className="text-[10px] text-muted">${r.relevant===null?'Abstrak sumber · bukan ringkasan AI':r.relevant?'✓ Positive menurut qrels':'Tidak berlabel positive pada qrels'}</span><button className="inline-flex items-center gap-1.5 text-[11px] font-semibold text-forest" onClick=${()=>openDetail(r)}>Baca & periksa skor<${Icon} name="arrow" size=${14}/></button></div></article>`)}</div><p className="mt-5 flex items-start gap-2 text-[11px] leading-5 text-muted"><${Icon} name="info" size=${14}/>Cosine mengukur kemiripan vektor, bukan persentase relevansi. Baca abstrak untuk menilai kesesuaiannya.</p></div>`:html`<div className="card overflow-hidden"><div className="dot-grid flex h-32 items-center justify-center"><div className="flex items-center gap-3 text-forest"><div className="rounded-xl border border-line bg-white p-3"><${Icon} name="search" size=${22}/></div><span className="text-[#9bb3a4]">·····</span><div className="rounded-xl border border-line bg-white p-3"><${Icon} name="cpu" size=${22}/></div><span className="text-[#9bb3a4]">·····</span><div className="rounded-xl border border-line bg-white p-3"><${Icon} name="book" size=${22}/></div></div></div><div className="px-6 pb-8 pt-5 text-center"><h2 className="text-base font-semibold">Satu pertanyaan, ribuan kemungkinan.</h2><p className="mx-auto mt-2 max-w-sm text-xs leading-6 text-muted">Tulis query sendiri atau pilih contoh di atas.<br/>Model akan menelusuri ${manifest?number(manifest.documents):'5.183'} abstrak dan memperlihatkan asal setiap skor.</p><div className="mt-5 flex flex-wrap justify-center gap-2"><span className="pill">384 dimensi</span><span className="pill">Cosine similarity</span><span className="pill">Exact retrieval</span></div></div></div>`}
        </div>
        <aside className="hidden space-y-4 2xl:block"><div className="card p-5"><p className="eyebrow">Di balik pencarian</p><h2 className="mt-3 text-sm font-semibold">Dari teks ke temuan</h2><div className="mt-5 space-y-5">${[['01','Normalisasi','Rapikan teks query'],['02','Tokenisasi','Ubah teks menjadi ID token'],['03','Embedding','Encode dengan MiniLM final'],['04','Cosine similarity','Bandingkan seluruh corpus'],['05','Ranking & hasil','Ambil Top-K dan abstrak']].map(([n,t,desc])=>html`<div key=${n} className="flex gap-3"><span className=${`flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-[9px] ${data?'bg-mint text-forest':'bg-paper text-muted'}`}>${data?html`<${Icon} name="check" size=${12}/>`:n}</span><div><p className="text-xs font-medium">${t}</p><p className="mt-1 text-[10px] text-muted">${desc}</p></div></div>`)}</div><button onClick=${()=>{setTab('trace');setView('pipeline');}} className="mt-6 inline-flex items-center gap-2 text-xs font-semibold text-forest">Jelajahi alurnya<${Icon} name="arrow" size=${14}/></button></div><div className="rounded-2xl bg-forest p-5 text-white"><p className="text-[9px] uppercase tracking-[.15em] text-[#b9d0c1]">Model penelitian</p><h3 className="mt-3 text-sm font-medium">${(data?.model||modelMode)==='pretrained'?'MiniLM pretrained.':'MiniLM untuk SciFact.'}</h3><p className="mt-3 text-[11px] leading-6 text-[#bdd1c5]">MNRL · 3 epoch · batch 8<br/>Checkpoint final penelitian</p><div className="mt-4 border-t border-white/15 pt-4 text-[10px] text-[#c8dbd0]">Seluruh pencarian di browser.<br/>Query tidak dikirim ke API.</div></div></aside>
        </div>`:view==='metrics'?html`<${Metrics} manifest=${manifest}/>`:html`<div className="max-w-3xl space-y-5"><div className="card p-7"><p className="eyebrow">Tentang penelitian</p><h1 className="mt-3 font-display text-3xl">Pencarian yang bisa ditelusuri.</h1><p className="mt-5 text-sm leading-7 text-muted">SciFind adalah demonstrasi penelitian Kelompok 6: sistem semantic search dokumen akademik menggunakan Sentence-BERT pada corpus BEIR–SciFact. MiniLM di-fine-tuning menggunakan pasangan query–dokumen positif dengan MNRL. Situs ini menyediakan bobot pretrained dan bobot final dalam format ONNX. Setiap model menggunakan embedding dokumen pasangannya sendiri.</p><div className="mt-6 grid grid-cols-2 gap-4">${[['5.183','dokumen kandidat'],['809','query training'],['919','pasangan positif'],['300','query pengujian']].map(([n,l])=>html`<div key=${l} className="rounded-xl bg-paper p-4"><p className="text-xl font-semibold">${n}</p><p className="mt-1 text-xs text-muted">${l}</p></div>`)}</div></div><div className="card p-7"><h2 className="font-semibold">Cara membaca hasil dengan tepat</h2><ul className="mt-4 list-disc space-y-3 pl-5 text-sm leading-6 text-muted"><li>Cosine adalah kemiripan embedding, bukan probabilitas bahwa artikel relevan.</li><li>Hasil dapat membahas, mendukung, atau membantah klaim. Aplikasi tidak memverifikasi kebenaran klaim.</li><li>Input encoder dibatasi 256 token. Abstrak penuh tetap dapat dibaca.</li><li>Qrels hanya tersedia untuk query benchmark yang cocok. Query bebas tidak diberi label relevansi buatan.</li><li>Semua dokumen dibandingkan secara exact; tidak memakai pencocokan kata kunci sebagai pengganti embedding.</li></ul></div><div className="card p-7"><h2 className="font-semibold">Verifikasi browser dengan notebook</h2><p className="mt-2 text-sm leading-6 text-muted">Bandingkan embedding dan Top-5 dari tiga query acuan terhadap keluaran Python checkpoint yang sama. Proses ini berjalan lokal di browser.</p><button disabled=${busy} className="btn mt-4" onClick=${()=>{setError('');setStatus('verifying');setVerification(null);worker.current.postMessage({type:'verify'});}}>${busy?'Memeriksa…':'Jalankan verifikasi'}</button>${verification&&html`<div className="mt-5 space-y-3" role="status">${verification.map(r=>html`<div key=${r.query} className="rounded-xl bg-paper p-3 text-xs leading-6"><p className="font-medium">${r.query}</p><p className="text-muted">${r.model} ? Selisih embedding maksimum ${r.maximumError.toExponential(2)} · Top-5 ${r.top5Matches?'cocok':'berbeda'}</p></div>`)}</div>`}${error&&html`<p role="alert" className="mt-3 text-sm text-red-700">${error}</p>`}</div><div className="card p-7 text-sm leading-7 text-muted"><p className="font-medium text-ink">Sumber & lisensi</p><a className="underline" href="https://huggingface.co/datasets/BeIR/scifact" target="_blank" rel="noreferrer">BEIR–SciFact · CC BY-SA 4.0</a><br/><a className="underline" href="https://huggingface.co/sentence-transformers/all-MiniLM-L6-v2" target="_blank" rel="noreferrer">Model awal all-MiniLM-L6-v2 · Apache 2.0</a><p className="mt-4 text-xs">Charlistio Aditirta Wijaya · Andreas Calvin · Monica Amrina Rosyada · Fitran Husein</p></div></div>`}
        <footer className="mt-12 flex flex-wrap items-center justify-between gap-3 border-t border-line pt-5 text-[10px] text-muted"><span>SciFind · Kelompok 06 · Temu Kembali Informasi</span><span className="flex items-center gap-1.5"><${Icon} name="layers" size=${12}/>MiniLM + SciFact · Diproses dalam browser</span></footer>
      </main>
    </div>
    ${selected&&html`<${DetailModal} key=${selected.variant+selected.id} result=${selected} breakdown=${breakdown} query=${data.normalized} onClose=${()=>setSelected(null)}/>`}
  </div>`;
}

export { App, Trace, Comparison, DetailModal, Metrics, Vector };
if (typeof document !== 'undefined' && document.getElementById('root')) {
  createRoot(document.getElementById('root')).render(html`<${App}/>`);
}
